//! Imported inductive-family records: what the kernel reduces with must be
//! what the kernel derives, never what a file says.
//!
//! A recursor record is executable reduction authority. The kernel's iota
//! step reads `rules` verbatim, K reduction (`try_to_cnstr_when_k`) fires on
//! `is_k` alone, and the recursor TYPE decides which motives, and so which
//! universes, the family may eliminate into. Constructor records are too:
//! projection reduction indexes fields by `num_params`, structure eta and K
//! read `num_fields`. Lean's kernel takes none of that from a file: replaying
//! an environment re-adds the inductive declaration, the kernel regenerates
//! its constructors and recursors, and `Lean.Replay` refuses a stored
//! constructor or recursor that is not equal to the regenerated one
//! (`checkPostponedConstructors` / `checkPostponedRecursors`; `Expr` equality
//! there is `Expr.eqv`, alpha-equivalence with binder annotations ignored).
//!
//! These are those checks for the structural import tier
//! (`Environment::extend_{inductives,constructors,recursors}_structural`, the
//! `.olean`/payload loader's family legs, which register a module's
//! inductives, then its constructors, then its recursors):
//!
//! - an inductive record's `num_indices` must be its type's arity minus
//!   `num_params`, the arity counted up to whnf as Lean's kernel counts it
//!   (at least the syntactic remainder when the codomain names a definition
//!   not yet resident);
//! - a constructor record's owner, position (`constructor_idx`),
//!   `num_params`, `num_fields` and universe parameters must be the ones its
//!   resident inductive and its own type determine;
//! - a recursor must EQUAL the recursor-table entry this kernel generates from
//!   the resident family with the same builder native admission uses
//!   (`compute_ctor_infos` + `build_recursor` / the HIT builders /
//!   `build_cases_on` / `build_rec_on`), field by field (expressions up to
//!   alpha, binder annotations and β — all inside the kernel's own
//!   definitional equality): universe arity, type,
//!   `num_params`, `num_indices`, `num_motives`, `num_minors`, `is_k`,
//!   argument order, eliminated inductive, and each rule's constructor, field
//!   count and RHS. A nested family is regenerated by re-admitting it through
//!   the kernel's own nested pipeline (`add_inductive_core`) on a scratch copy.
//!
//! A disagreement REFUSES the record with
//! [`EnvError::ImportedFamilyRecordMismatch`] naming the constant —
//! fail-closed, never patched. The one field adopted rather than compared is
//! `recursive_fields`, Clean-internal metadata Lean's format does not carry.
//!
//! Scope, so nobody reads more into a pass than it carries: this establishes
//! that the records the reduction engine consults are the ones the kernel
//! derives from the imported family. It does NOT re-check a non-nested family
//! itself (positivity, universe constraints, constructor typing); that
//! residual is the census row `ind-meta-structural` in
//! `data/env_bypass_census.json`. A nested family's regeneration IS a full
//! checked re-admission, so it does not carry that residual.

use std::collections::HashMap;

use super::inductive_lean_replay::lean_expr_eqv;
use super::types::EnvError;
use super::Environment;
use crate::expr::{Expr, ExprKind};
use crate::inductive::{count_pi_args, ConstructorVal, InductiveDecl, InductiveVal, RecursorVal};
use crate::level::{Level, ZeroReading};
use crate::name::{Name, NameInner};

/// Successful recursor-table generations per matching mutual block, shared
/// across one registration batch. Failures stay under the requested family
/// root so their diagnostics, and their once-per-root cost, are unchanged.
pub(crate) type GeneratedRecursorCache = HashMap<Name, Result<Vec<RecursorVal>, String>>;

/// The refusal for one imported family record.
fn refuse(record: &Name, detail: impl Into<String>) -> EnvError {
    EnvError::ImportedFamilyRecordMismatch {
        name: record.clone(),
        detail: detail.into(),
    }
}

/// The family root a recursor-table name belongs to: `T.rec`, `T.casesOn` and
/// `T.recOn` belong to `T`, and a nested block's auxiliary `T.rec_<n>` belongs
/// to `T` as well (Lean names every auxiliary recursor after the block's first
/// type). Anything else is not a name the kernel generates a recursor under.
fn recursor_family_root(name: &Name) -> Option<Name> {
    let NameInner::Str(parent, suffix) = name.inner() else {
        return None;
    };
    let suffix: &str = suffix.as_ref();
    let is_aux = suffix
        .strip_prefix("rec_")
        .is_some_and(|n| !n.is_empty() && n.bytes().all(|b| b.is_ascii_digit()));
    (matches!(suffix, "rec" | "casesOn" | "recOn") || is_aux).then(|| parent.as_ref().clone())
}

/// Node visits one β-comparison may spend, and the deepest recursion it may
/// reach (each contraction re-normalizes its result one level down). A Lean
/// record that differs from the regenerated one only by β carries a few
/// shallow redexes (a nested family's dependent container parameter,
/// instantiated without reduction); exhausting either bound refuses the record
/// rather than letting a crafted, non-normalizing or exponentially shared
/// term hang the import.
const BETA_FUEL: u64 = 4_000_000;
const BETA_MAX_DEPTH: u32 = 10_000;

/// β-normal form within the bounds, or `None` when either runs out. The input
/// is file data, not a checked term, so unlike `Expr::beta_normalize` this
/// cannot assume termination.
fn beta_normal_bounded(e: &Expr, fuel: &mut u64, depth: u32) -> Option<Expr> {
    if depth >= BETA_MAX_DEPTH {
        return None;
    }
    crate::expr::stack_safe(|| beta_bounded(e, fuel, depth + 1))
}

fn beta_bounded(e: &Expr, fuel: &mut u64, depth: u32) -> Option<Expr> {
    *fuel = fuel.checked_sub(1)?;
    Some(match e.kind() {
        ExprKind::App(f, a) => {
            let head = beta_normal_bounded(f, fuel, depth)?;
            let arg = beta_normal_bounded(a, fuel, depth)?;
            if let ExprKind::Lam(_, _, body) = head.kind() {
                return beta_normal_bounded(&body.instantiate(&arg), fuel, depth);
            }
            Expr::app(head, arg)
        }
        ExprKind::Lam(bi, ty, body) => Expr::lam(
            *bi,
            beta_normal_bounded(ty, fuel, depth)?,
            beta_normal_bounded(body, fuel, depth)?,
        ),
        ExprKind::Pi(bi, ty, body) => Expr::pi(
            *bi,
            beta_normal_bounded(ty, fuel, depth)?,
            beta_normal_bounded(body, fuel, depth)?,
        ),
        // Every other variant is compared as it stands (Let/Proj/MData and
        // the extension variants do not occur in a generated recursor).
        _ => e.clone(),
    })
}

/// Lean's `==` ([`lean_expr_eqv`]: alpha-equal, binder annotations
/// ignored), or equal after β-normalizing both sides — β is part of the kernel's definitional equality, so a record
/// β-equal to the generated one infers and reduces identically up to def-eq.
/// `Err` when the budget is exhausted.
fn eq_modulo_beta(file: &Expr, generated: &Expr) -> Result<bool, String> {
    if lean_expr_eqv(file, generated) {
        return Ok(true);
    }
    let mut fuel = BETA_FUEL;
    let exhausted = || "β-normalization budget exhausted comparing to the generated recursor";
    let file = beta_normal_bounded(file, &mut fuel, 0).ok_or_else(|| exhausted().to_string())?;
    let generated =
        beta_normal_bounded(generated, &mut fuel, 0).ok_or_else(|| exhausted().to_string())?;
    Ok(lean_expr_eqv(&file, &generated))
}

/// Compare an imported recursor against the kernel-generated one. `Ok` only
/// when every field the reduction engine consults agrees.
fn compare_recursor(
    file: &RecursorVal,
    generated: &RecursorVal,
    profile: crate::level::LeanLevelProfile,
) -> Result<(), String> {
    if file.level_params.len() != generated.level_params.len() {
        return Err(format!(
            "universe parameters: file has {} ({:?}), kernel generates {} ({:?}) — \
             the elimination universe differs",
            file.level_params.len(),
            file.level_params,
            generated.level_params.len(),
            generated.level_params
        ));
    }
    let nums = |r: &RecursorVal| (r.num_params, r.num_indices, r.num_motives, r.num_minors);
    if nums(file) != nums(generated) {
        return Err(format!(
            "(num_params, num_indices, num_motives, num_minors): file {:?}, kernel generates {:?}",
            nums(file),
            nums(generated)
        ));
    }
    if file.is_k != generated.is_k {
        return Err(format!(
            "K-like flag: file says k={}, kernel generates k={}",
            file.is_k, generated.is_k
        ));
    }
    if file.arg_order != generated.arg_order {
        return Err(format!(
            "argument order: file {:?}, kernel generates {:?}",
            file.arg_order, generated.arg_order
        ));
    }
    if file.inductive_name != generated.inductive_name {
        return Err(format!(
            "eliminated inductive: file {}, kernel generates {}",
            file.inductive_name, generated.inductive_name
        ));
    }
    // Rename the generated universe parameters to the file's, positionally
    // (the substitution is simultaneous, so a permutation is safe), with
    // Lean's `instantiate` so a stored `max`/`imax` the file keeps verbatim is
    // not collapsed by Clean's smart constructors (DECISIONS R150).
    let file_levels: Vec<Level> = file
        .level_params
        .iter()
        .map(|p| Level::param(p.clone()))
        .collect();
    let rename = |e: &Expr| {
        if profile == crate::level::LeanLevelProfile::Lean430 {
            return e.lean_instantiate_level_params_kept(&generated.level_params, &file_levels);
        }
        e.lean_instantiate_level_params_kept_in_profile(
            &generated.level_params,
            &file_levels,
            profile,
        )
    };
    if !eq_modulo_beta(&file.type_, &rename(&generated.type_))? {
        return Err("type differs from the generated recursor type".to_string());
    }
    if file.rules.len() != generated.rules.len() {
        return Err(format!(
            "{} rules, kernel generates {}",
            file.rules.len(),
            generated.rules.len()
        ));
    }
    for (idx, (f, g)) in file.rules.iter().zip(&generated.rules).enumerate() {
        if f.constructor_name != g.constructor_name {
            return Err(format!(
                "rule {idx}: file names constructor {}, kernel generates {}",
                f.constructor_name, g.constructor_name
            ));
        }
        if f.num_fields != g.num_fields {
            return Err(format!(
                "rule {idx} ({}): file num_fields={}, kernel generates {}",
                f.constructor_name, f.num_fields, g.num_fields
            ));
        }
        if !eq_modulo_beta(&f.rhs, &rename(&g.rhs))? {
            return Err(format!(
                "rule {idx} ({}): iota right-hand side differs from the generated rule",
                f.constructor_name
            ));
        }
    }
    Ok(())
}

impl Environment {
    /// Share a successful generation only when both names reconstruct the
    /// same declaration. Imported `all_names` is structural metadata, not
    /// authority: a common first name alone does not establish that identity.
    /// The ordered members determine all type/constructor lookups, while the
    /// requested member supplies `num_params` and `level_params` to
    /// `inductive_decl_of`. Family tables stay immutable during the batch.
    fn imported_recursor_cache_root(&self, root: &Name) -> Name {
        let Some(member) = self.get_inductive(root) else {
            return root.clone();
        };
        let Some(head) = member.all_names.first() else {
            return root.clone();
        };
        if head == root {
            return root.clone();
        }
        let Some(first) = self.get_inductive(head) else {
            return root.clone();
        };
        if member.all_names.contains(root)
            && member.all_names == first.all_names
            && member.num_params == first.num_params
            && member.level_params == first.level_params
        {
            head.clone()
        } else {
            root.clone()
        }
    }

    /// Every recursor-table entry native admission generates for the
    /// non-nested block `decl` (same builders, same dispatch, same mutual minor
    /// offsets as `add_inductive_impl_inner`), read off the family's
    /// already-registered records, with `zero` as the `is_zero` of the
    /// elimination level and the K target. Read-only.
    fn generate_block_recursors(
        &self,
        decl: &InductiveDecl,
        zero: ZeroReading,
    ) -> Result<Vec<RecursorVal>, EnvError> {
        let all_ctor_infos: Vec<_> = decl
            .types
            .iter()
            .flat_map(|t| self.compute_ctor_infos(t, decl))
            .collect();
        let is_trunc_hit = crate::inductive::is_prop_truncation_shape(decl);
        let is_susp_hit = crate::inductive::is_suspension_shape(decl);
        // The result levels up to whnf, by the same helper native admission
        // uses (`Environment::block_result_levels`): a recursor stored for a
        // `δ`-`Prop` family is compared against the Prop-only recursor Lean's
        // kernel generates, never against one built from the syntactic head.
        let result_levels = self.block_result_levels(decl)?;
        let mut generated = Vec::with_capacity(3 * decl.types.len());
        let mut minor_offset = 0usize;
        for (ind_type, result_level) in decl.types.iter().zip(&result_levels) {
            let ctor_infos = self.compute_ctor_infos(ind_type, decl);
            let rec = if is_trunc_hit {
                self.build_truncation_recursor(ind_type, decl)?
            } else if is_susp_hit {
                self.build_suspension_recursor(ind_type, decl)?
            } else {
                self.build_recursor(
                    &ind_type.name,
                    decl,
                    result_level,
                    &ctor_infos,
                    &all_ctor_infos,
                    minor_offset,
                    zero,
                )?
            };
            if !(is_trunc_hit || is_susp_hit || Self::has_path_constructor(ind_type)) {
                let name = &ind_type.name;
                generated.push(self.build_cases_on(
                    name,
                    decl,
                    result_level,
                    &ctor_infos,
                    &all_ctor_infos,
                    minor_offset,
                    zero,
                )?);
                generated.push(self.build_rec_on(
                    name,
                    decl,
                    result_level,
                    &ctor_infos,
                    &all_ctor_infos,
                    minor_offset,
                    &rec.type_,
                    zero,
                )?);
            }
            generated.push(rec);
            minor_offset += ind_type.constructors.len();
        }
        Ok(generated)
    }

    /// The regenerated entries for the family rooted at `root`, or why none
    /// exist.
    pub(super) fn regenerate_family(&self, root: &Name) -> Result<Vec<RecursorVal>, String> {
        let decl = self
            .inductive_decl_of(root)
            .ok_or_else(|| format!("family {root} is not resident with all its constructors"))?;
        let nested = decl
            .types
            .iter()
            .any(|t| self.get_inductive(&t.name).is_some_and(|ind| ind.is_nested));
        if nested {
            return self.regenerate_nested_family(root);
        }
        self.generate_block_recursors(&decl, self.zero_reading())
            .map_err(|e| format!("generation failed for family {root}: {e}"))
    }

    /// Whether `rec`, refused against this environment's own generation,
    /// equals the entry pinned Lean's kernel generates from the same resident
    /// family: the non-nested block regenerated with rc2's STRUCTURAL
    /// `is_zero` (`inductive.cpp:517,557`), asked only where this environment
    /// reads the semantic one (`Extended`; DECISIONS R150).
    ///
    /// A Lean `.olean` stores the recursor Lean's kernel generated, so where
    /// the two readings disagree (a field or result level such as
    /// `Sort (max 0 0)`, which decodes verbatim) the honest record is Lean's.
    /// Admitting it is sound under `Extended`: [`ZeroReading::Structural`]
    /// reads a level as `0` only where [`ZeroReading::Semantic`] does, so
    /// Lean's entry eliminates into no universe Clean's does not, and is
    /// K-like only where Clean's is. Every other field is compared exactly as
    /// against this environment's own generation. A nested family is not
    /// retried: its generation is a checked re-admission of the block with
    /// its auxiliary types, whose records neither reading changes
    /// (`test_zero_reading_never_separates_nested_generations`), so a
    /// refusal there is about something else.
    fn matches_lean_structural_generation(&self, rec: &RecursorVal, root: &Name) -> bool {
        if self.zero_reading() != ZeroReading::Semantic {
            return false;
        }
        let Some(decl) = self.inductive_decl_of(root) else {
            return false;
        };
        let nested = decl
            .types
            .iter()
            .any(|t| self.get_inductive(&t.name).is_some_and(|ind| ind.is_nested));
        if nested {
            return false;
        }
        let Ok(generated) = self.generate_block_recursors(&decl, ZeroReading::Structural) else {
            return false;
        };
        generated
            .iter()
            .find(|g| g.name == rec.name)
            .is_some_and(|g| compare_recursor(rec, g, self.lean_level_profile()).is_ok())
    }

    /// A nested family's recursors come out of the kernel's own nested
    /// pipeline (Lean-parity elimination into an auxiliary mutual block, then
    /// restoration of `T.rec` and `T.rec_<n>`), which admission runs through
    /// provisional registrations. So the family is re-admitted through the
    /// full checked `add_inductive_core` on a scratch copy, by the SAME
    /// re-admission the `.olean` replay lanes use
    /// (`Environment::lean_replay_admit_block`): a nested family is fully
    /// kernel-checked, and one the kernel refuses has no recursor at all.
    /// Costs one environment clone per nested family.
    fn regenerate_nested_family(&self, root: &Name) -> Result<Vec<RecursorVal>, String> {
        let replayed = self
            .lean_replay_admit_block(std::slice::from_ref(root))
            .map_err(|e| format!("nested family {root}: {e}"))?;
        Ok(replayed
            .generated_recursors
            .iter()
            .filter_map(|name| replayed.scratch.get_recursor(name).cloned())
            .collect())
    }

    /// Verify one imported recursor against the recursor-table entry of the
    /// same name this kernel generates from the resident family, and return
    /// the record to register: the file's (its type keeps the binder
    /// annotations the elaborator reads) with the kernel's own
    /// `recursive_fields`, which Lean's format does not carry at all.
    ///
    /// # Errors
    /// [`EnvError::ImportedFamilyRecordMismatch`] naming the recursor when the
    /// name is not one the kernel generates, the family is missing or
    /// incomplete, a nested family is refused by kernel admission, generation
    /// fails, or any compared field disagrees.
    pub(crate) fn admit_imported_recursor(
        &self,
        mut rec: RecursorVal,
        cache: &mut GeneratedRecursorCache,
    ) -> Result<RecursorVal, EnvError> {
        let root = recursor_family_root(&rec.name).ok_or_else(|| {
            refuse(
                &rec.name,
                "not a name the kernel generates a recursor under",
            )
        })?;
        let shared_root = self.imported_recursor_cache_root(&root);
        let cache_key = if matches!(cache.get(&shared_root), Some(Ok(_))) {
            shared_root
        } else if cache.contains_key(&root) {
            root.clone()
        } else {
            // Generate from the ORIGINAL requested root. On error, neither
            // relabel its diagnostic nor repeat the work under the head.
            let generated = self.regenerate_family(&root);
            let key = if generated.is_ok() {
                shared_root
            } else {
                root.clone()
            };
            cache.insert(key.clone(), generated);
            key
        };
        let generated = cache
            .get(&cache_key)
            .ok_or_else(|| refuse(&rec.name, "missing batch-local recursor generation"))?
            .as_ref()
            .map_err(|detail| refuse(&rec.name, detail.clone()))?;
        let counterpart = generated
            .iter()
            .find(|g| g.name == rec.name)
            .ok_or_else(|| {
                refuse(
                    &rec.name,
                    format!("the kernel generates no recursor of this name for family {root}"),
                )
            })?;
        if let Err(detail) = compare_recursor(&rec, counterpart, self.lean_level_profile()) {
            if !self.matches_lean_structural_generation(&rec, &root) {
                return Err(refuse(&rec.name, detail));
            }
        }
        // The zero reading decides the universe parameters (and so the levels
        // a rule applies the recursor at) and `is_k`, never which fields are
        // recursive, so either generation's `recursive_fields` is the
        // family's.
        for (rule, generated_rule) in rec.rules.iter_mut().zip(&counterpart.rules) {
            rule.recursive_fields = generated_rule.recursive_fields.clone();
        }
        Ok(rec)
    }

    /// Verify an imported inductive record's derived arity metadata.
    ///
    /// Lean's kernel counts a type former's arity by the same loop that finds
    /// its result level (`check_inductive_types`: whnf between binders), so a
    /// type former hidden behind a definition (`ObjectProperty C := C → Prop`)
    /// carries indices no syntactic binder shows. The arity is read by that
    /// loop here too (`Environment::type_former_result_sort`, the helper
    /// native admission and recursor regeneration use), and must split
    /// EXACTLY as `num_params + num_indices`. When the loop cannot finish
    /// (the codomain names a definition of the same module, registered after
    /// the module's families), the syntactic remainder is a lower bound, as
    /// before; the recursor is regenerated after those definitions, by the
    /// same helper, and refused if the family's elimination universe differs.
    ///
    /// # Errors
    /// [`EnvError::ImportedFamilyRecordMismatch`] when `num_params` exceeds the
    /// type's arity or `num_indices` is not the remainder.
    pub(crate) fn check_imported_inductive(&self, ind: &InductiveVal) -> Result<(), EnvError> {
        let split_ok = match self.type_former_result_sort(&ind.type_) {
            Some(sort) => {
                ind.num_params <= sort.arity && ind.num_indices == sort.arity - ind.num_params
            }
            None => {
                let arity = count_pi_args(&ind.type_);
                ind.num_params <= arity && ind.num_indices >= arity - ind.num_params
            }
        };
        if !split_ok {
            return Err(refuse(
                &ind.name,
                format!(
                    "type arity {} does not split as num_params={} + num_indices={}",
                    count_pi_args(&ind.type_),
                    ind.num_params,
                    ind.num_indices
                ),
            ));
        }
        Ok(())
    }

    /// Verify an imported constructor record against its resident inductive
    /// and its own type.
    ///
    /// # Errors
    /// [`EnvError::ImportedFamilyRecordMismatch`] when the owner is not
    /// resident or does not list the constructor at `constructor_idx`, or
    /// `num_params`, `num_fields` or the universe parameters disagree.
    pub(crate) fn check_imported_constructor(&self, ctor: &ConstructorVal) -> Result<(), EnvError> {
        let ind = self.inductives.get(&ctor.inductive_name).ok_or_else(|| {
            refuse(
                &ctor.name,
                format!("owning inductive {} is not resident", ctor.inductive_name),
            )
        })?;
        let position = ind.constructor_names.iter().position(|n| n == &ctor.name);
        if position != Some(ctor.constructor_idx as usize) {
            return Err(refuse(
                &ctor.name,
                format!(
                    "constructor_idx={} but {} lists it at {position:?}",
                    ctor.constructor_idx, ind.name
                ),
            ));
        }
        if ctor.level_params != ind.level_params {
            return Err(refuse(
                &ctor.name,
                format!(
                    "universe parameters {:?} differ from {}'s {:?}",
                    ctor.level_params, ind.name, ind.level_params
                ),
            ));
        }
        let arity = count_pi_args(&ctor.type_);
        if ctor.num_params != ind.num_params
            || arity < ind.num_params
            || ctor.num_fields != arity - ind.num_params
        {
            return Err(refuse(
                &ctor.name,
                format!(
                    "num_params={} num_fields={} but the type has arity {arity} and {} has \
                     num_params={}",
                    ctor.num_params, ctor.num_fields, ind.name, ind.num_params
                ),
            ));
        }
        Ok(())
    }
}

